const triggerData = $('Telegram Trigger').first().json;
const rawText = triggerData.message?.text || triggerData.message?.caption || "";
const textLower = rawText.toLowerCase();

// 1. 识别品牌
let brand = "";
if (textLower.includes("[BRAND_A]") || textLower.includes("[BRAND_A]")) {
  brand = "[BRAND_A]";
} else if (textLower.includes("[BRAND_C]") || textLower.includes("[BRAND_C]") || textLower.includes("[BRAND_C]")) {
  brand = "[BRAND_C]";
} else if (textLower.includes("[BRAND_B]") || textLower.includes("[BRAND_B]")) {
  brand = "[BRAND_B]";
} else {
  brand = $getWorkflowStaticData('global').lastBrand || "[BRAND_C]"; 
}

// 2. 将 Telegram 的 entities（加粗、斜体等）转换成 HTML 标签
function convertTelegramFormat(message, plainText) {
    if (!message || !plainText) return plainText || "";
    let entities = message.entities || message.caption_entities || [];
    if (!entities || entities.length === 0) return plainText;

    // 按 offset 降序排序，从后往前替换，防止索引错位
    entities.sort((a, b) => b.offset - a.offset);
    let result = plainText;

    for (let entity of entities) {
        let start = entity.offset;
        let end = entity.offset + entity.length;
        let startTag = "";
        let endTag = "";

        switch (entity.type) {
            case "bold": startTag = "<b>"; endTag = "</b>"; break;
            case "italic": startTag = "<i>"; endTag = "</i>"; break;
            case "underline": startTag = "<u>"; endTag = "</u>"; break;
            case "strikethrough": startTag = "<s>"; endTag = "</s>"; break;
            case "code": startTag = "<code>"; endTag = "</code>"; break;
            case "pre": startTag = "<pre>"; endTag = "</pre>"; break;
            case "text_link": startTag = `<a href="${entity.url}">`; endTag = "</a>"; break;
        }

        if (startTag && endTag) {
            result = result.slice(0, start) + startTag + result.slice(start, end) + endTag + result.slice(end);
        }
    }
    return result;
}

// 3. 处理用户的当前输入（将 TG 实体转为 HTML）
let userInputHtml = convertTelegramFormat(triggerData.message, rawText);
// 顺便把可能混进去的 Markdown 也转成 HTML
userInputHtml = userInputHtml.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

// 4. 处理 draft_content（把缓存里的 Markdown 统一转为 HTML）
let rawDraft = $getWorkflowStaticData('global').lastDraft || "";
let draftHtml = rawDraft.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');

return [{
  json: {
    brand: brand,
    user_input: userInputHtml,
    draft_content: draftHtml
  }
}];

const inputData = $input.first().json;
const rawUserInput = inputData.user_input || ""; 
const matchInput = rawUserInput.toLowerCase().trim();

let draftContent = inputData.draft_content || "";
const confirmWords = ["过", "ok", "okey", "通过", "发布", "yes"];
const hasConfirmWord = confirmWords.some(word => matchInput.includes(word));

if (!draftContent && hasConfirmWord) {
    draftContent = $getWorkflowStaticData('global').lastDraft || "";
}

// 品牌识别
let brand = inputData.brand || "";
let brand_code = "";
let default_partition = "";

if (matchInput.includes("[BRAND_A]") || matchInput.includes("[BRAND_A]") || brand === "[BRAND_A]") {
    brand = "[BRAND_A]"; brand_code = "BRAND-B1"; default_partition = "P2"; 
} else if (matchInput.includes("[BRAND_C]") || matchInput.includes("[BRAND_C]") || matchInput.includes("[BRAND_C]") || brand === "[BRAND_C]") {
    brand = "[BRAND_C]"; brand_code = "BRAND-B3"; default_partition = "P10"; 
} else if (matchInput.includes("[BRAND_B]") || brand === "[BRAND_B]") {
    brand = "[BRAND_B]"; brand_code = "BRAND-B2"; default_partition = "P4"; 
}

// ==========================================
// 🛡️ 新增：在此处直接解析指令，并存入全局缓存
// ==========================================
const langMap = {
  'en': 'en', '英语': 'en', '英文': 'en', '英': 'en',
  'ru': 'ru', '俄语': 'ru', '俄文': 'ru', '俄': 'ru',
  'pt': 'pt', '葡语': 'pt', '葡萄牙': 'pt', '葡': 'pt', '巴西': 'pt',
  'es': 'es', '西语': 'es', '西班牙': 'es', '西': 'es', '西语区': 'es',
  'fa': 'fa', '波斯语': 'fa', '波斯': 'fa', '伊朗': 'fa'
};

let selectedLangs = [];
const tokens = matchInput.replace(/[，,\s\/]+/g, ',').split(',');

for (let token of tokens) {
  token = token.trim();
  if (!token) continue;
  if (['过', '通过', 'ok'].includes(token)) continue;
  if (langMap[token] && !selectedLangs.includes(langMap[token])) {
    selectedLangs.push(langMap[token]);
  }
}

// 存入全局缓存，供跨工作流使用
const staticData = $getWorkflowStaticData('global');
staticData.selectedLangs = selectedLangs.length > 0 ? selectedLangs : ['en', 'ru', 'pt', 'es', 'fa'];
console.log("🚀 已将审核指令存入全局，白名单: ", staticData.selectedLangs);
// ==========================================

return {
  json: {
    user_input: rawUserInput,       
    draft_content: draftContent, 
    brand: brand,
    brand_code: brand_code,             
    default_partition: default_partition 
  }
};

// 1. 接收工作流B返回的翻译结果
const data = $input.first().json;

// 🚨 核心修复：从上游直接抓取真实品牌
const realBrand = $('格式化代码').first().json.brand || "[BRAND_C]";
data.brand = realBrand;

const staticData = $getWorkflowStaticData('global');

// 🛡️ 直接从全局缓存读取白名单
const selectedLangs = staticData.selectedLangs || ['en', 'ru', 'pt', 'es', 'fa'];
const allLangs = ['en', 'ru', 'pt', 'es', 'fa'];

console.log("🛡️ 开始执行拦截，当前白名单: ", selectedLangs);

// 执行数据拦截：没有在白名单里的，直接清空
for (let lang of allLangs) {
  if (!selectedLangs.includes(lang)) {
    if (data[lang] !== undefined) {
        data[lang] = ""; 
    }
  }
}

// 存入全局缓存 (此时存的是被“安检”过的数据)
staticData.translatedTexts = data; 
staticData.lastBrand = realBrand; 

return [{ json: data }];

