const fullText = $json.output || "";
// 确保这里一定能拿到品牌
let brand = $('格式化代码').first().json.brand || "[BRAND_C]";

// 强制纠正品牌，防止串线
const lowerText = fullText.toLowerCase();
if (lowerText.includes("[BRAND_A]") || lowerText.includes("[BRAND_A]")) {
  brand = "[BRAND_A]";
} else if (lowerText.includes("[BRAND_B]")) {
  brand = "[BRAND_B]";
}

// 🚨 核心：存进全局缓存！如果这一步没执行，后面全崩
const staticData = $getWorkflowStaticData('global');
staticData.lastDraft = fullText;
staticData.lastBrand = brand;

return { json: { rawAiOutput: fullText, brand: brand } };

// Emoji 字典（请根据你实际的需求，把全部字典补全）
const emojiMap = {
  "🚀": '<tg-emoji emoji-id="5188481279963715781">🚀</tg-emoji>',
  "🔥": '<tg-emoji emoji-id="5424972470023104089">🔥</tg-emoji>',
  "✔️": '<tg-emoji emoji-id="5206607081334906820">✔️</tg-emoji>',
  "📣": '<tg-emoji emoji-id="5424818078833715060">📣</tg-emoji>',
  // ... 如果你有其他 emoji，补充在这里
};

let text = $json.rawAiOutput || "";

// 统一把上游 AI 可能乱吐的 <br> 变成真正的换行符 \n
text = text.replace(/<br\s*\/?>/gi, '\n');

// 1. 把 Markdown 的 ** 替换为 <b>
text = text.replace(/\*\*(.*?)\*\*/g, '<b>$1</b>');
text = text.replace(/\*(.*?)\*/g, '<i>$1</i>');
text = text.replace(/\[(.*?)\]\((.*?)\)/g, '<a href="$2">$1</a>'); // Markdown 链接转 HTML

// 2. 强制排版：把列表项换行，解决拥挤
text = text.replace(/(?<!\n)([•✔]|\b\d+\.)/g, '\n$1');
text = text.replace(/\n{3,}/g, '\n\n').trim();

// 3. 替换动态 Emoji
for (const [key, value] of Object.entries(emojiMap)) {
  text = text.split(key).join(value);
}

// 生成两份文本
const draftText = text; // 给原生 TG 发草稿用的
const rawAiOutput = text.replace(/\n/g, '<br>'); // 给最终 sendRichMessage 存缓存用的

return {
  json: {
    rawAiOutput: rawAiOutput, 
    draftText: draftText,     
    brand: $json.brand
  }
};

const staticData = $getWorkflowStaticData('global');
const trans = staticData.translatedTexts || {};

// 修正：只要有任意语言的数据，就放行（不再强制要求必须有 en）
const hasAnyData = Object.values(trans).some(val => val && String(val).trim() !== "");
if (!hasAnyData) {
    throw new Error("缓存中无数据，请先完成一审和翻译。");
}

// 直接把触发器的 message 透传下去，为下载图片节点提供上下文
const triggerData = $('本地化审核触发').first().json;
return [{ json: { message: triggerData.message } }];

const msg = $json.message;
if (!msg.reply_to_message) throw new Error("没有引用消息！");

const rawReplyText = msg.reply_to_message.text || "";
const opinion = msg.text || "";

let targetLang = "";
if (rawReplyText.includes("🇺🇸 EN:")) targetLang = "en";
else if (rawReplyText.includes("🇷🇺 RU:")) targetLang = "ru";
else if (rawReplyText.includes("🇵🇹 PT:")) targetLang = "pt";
else if (rawReplyText.includes("🇪🇸 ES:")) targetLang = "es";
else if (rawReplyText.includes("🇮🇷 FA:")) targetLang = "fa";

if (!targetLang) throw new Error("找不到语言前缀！");

// 🚨 从 translatedTexts 缓存中拿带 HTML 的原文
const staticData = $getWorkflowStaticData('global');
const currentTexts = staticData.translatedTexts || {};
let originalText = currentTexts[targetLang] || rawReplyText.replace(/^🇺🇸 EN:|^🇷🇺 RU:|^🇵🇹 PT:|^🇪🇸 ES:|^🇮🇷 FA:/, "").trim();

return [{ json: { targetLang, originalText, opinion } }];

let aiOutput = $json.output || "";
let cleanOutput = aiOutput.replace(/```json/g, "").replace(/```/g, "").trim();
let parsed = {};
try {
    parsed = JSON.parse(cleanOutput);
} catch (e) {
    const jsonMatch = cleanOutput.match(/\{[\s\S]*\}/);
    if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
    else throw new Error(`AI 输出格式错误`);
}

const newText = parsed.rewrittenText;
if (!newText || newText.length < 5) throw new Error(`AI 未正确生成文本`);

// 1. 精准更新 translatedTexts 缓存
const staticData = $getWorkflowStaticData('global');
if (!staticData.translatedTexts) staticData.translatedTexts = {};
const targetLang = $('提取旧数据和意见').item.json.targetLang;

staticData.translatedTexts[targetLang] = newText;

// 🚨 核心修改：取出更新后的全量数据，准备重新发送二审
const trans = staticData.translatedTexts;
const langs = [
  { flag: "🇺🇸 EN:", text: trans.en },
  { flag: "🇷🇺 RU:", text: trans.ru },
  { flag: "🇵🇹 PT:", text: trans.pt },
  { flag: "🇪🇸 ES:", text: trans.es },
  { flag: "🇮🇷 FA:", text: trans.fa }
];

// 过滤空文本，组装成跟一审一模一样的格式
const messages = langs
  .filter(l => l.text && l.text.trim().length > 0)
  .map(l => ({
    // 去掉 HTML 的 <br>，替换为真实换行符发给 TG 节点
    json: { text: `${l.flag}\n${l.text.replace(/<br\s*\/?>/gi, '\n')}` }
  }));

// 最后加上一条提示消息
messages.push({ 
    json: { text: `-------------------\n修改已生效，请重新审核以上全量草稿。\n若需继续修改，请长按引用；\n若确认无误，请直接发送一张图片执行终极发布。` } 
});

// 返回包含多条的数组
return messages;

const data = $input.first().json;
const staticData = $getWorkflowStaticData('global');
// 缓存已经在上一节点存过了，这里直接发

const langs = [
  { flag: "🇺🇸 EN:", text: data.en },
  { flag: "🇷🇺 RU:", text: data.ru },
  { flag: "🇵🇹 PT:", text: data.pt },
  { flag: "🇪🇸 ES:", text: data.es },
  { flag: "🇮🇷 FA:", text: data.fa }
];

const messages = langs
  .filter(l => l.text && l.text.trim().length > 0)
  .map(l => ({
    // 原生 TG 节点用真实的换行，并且你已经在节点里开启了 HTML mode，<b> 会被正常渲染
    json: { text: `${l.flag}\n${l.text.replace(/<br\s*\/?>/gi, '\n')}` }
  }));

messages.push({ json: { text: `-------------------\n请直接发送一张图片执行终极发布。\n若需修改，请长按上方任意一条语言消息引用回复。` } });

return messages;

