// 1. 获取 AI 刚生成的新翻译数据（假设上个节点叫“解析新翻译并存入缓存”）
// 注意：这里去读取上游节点的输出，如果是单条文本，直接提取
const item = $input.first().json;
const rawText = item.text || item.content || item.output || "";

// 2. 取出 920+ 字典
const staticData = $getWorkflowStaticData('global');
const rawEmojiMap = staticData.globalEmojiMap || {};

// 3. 核心清洗函数
const cleanText = (text) => {
    if (!text) return "";
    let cleaned = text
        .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>'); // 顺手修一下粗体

    const segmenter = new Intl.Segmenter('en', { granularity: 'grapheme' });
    let result = "";

    for (const { segment } of segmenter.segment(cleaned)) {
        // 查字典（兼容变体符）
        const id = rawEmojiMap[segment] || rawEmojiMap[segment.replace(/\uFE0F/g, '')];

        if (id) {
            const cleanId = String(id).replace(/[^0-9]/g, '');
            result += `<tg-emoji emoji-id="${cleanId}">${segment}</tg-emoji>`;
        } else {
            result += segment;
        }
    }
    return result.trim();
};

// 4. 返回清洗后的文本给 TG 节点发送
return [{
    json: {
        ...item, // 保留原有的所有字段
        text: cleanText(rawText) // 把清洗后的文本回写
    }
}];
